import base64
import hashlib
import email
import email.mime.text
import email.mime.multipart
import email.mime.application
from email.utils import formatdate
import sys


def create_email_from_request(request):
    """Build an RFC 5322 email message from the request."""
    if not isinstance(request, dict):
        raise ValueError("invalid request")

    required_fields = ['from', 'to', 'subject', 'date', 'message_id', 'body', 'attachments']
    for field in required_fields:
        if field not in request:
            raise ValueError("invalid request")

    from_addr = request['from']
    to_list = request['to']
    subject = request['subject']
    date = request['date']
    message_id = request['message_id']
    body = request['body']
    attachments = request['attachments']

    # Validate from
    if not isinstance(from_addr, str):
        raise ValueError("invalid request")

    # Validate to
    if not isinstance(to_list, list) or len(to_list) < 1 or len(to_list) > 8:
        raise ValueError("invalid request")
    for addr in to_list:
        if not isinstance(addr, str):
            raise ValueError("invalid request")

    # Validate subject
    if not isinstance(subject, str) or not subject:
        raise ValueError("invalid request")

    # Validate date
    if not isinstance(date, int):
        raise ValueError("invalid request")

    # Validate message_id
    if not isinstance(message_id, str) or not message_id.startswith('<') or not message_id.endswith('>'):
        raise ValueError("invalid request")

    # Validate body
    if not isinstance(body, str):
        raise ValueError("invalid request")

    # Validate attachments
    if not isinstance(attachments, list) or len(attachments) > 8:
        raise ValueError("invalid request")
    for att in attachments:
        if not isinstance(att, dict):
            raise ValueError("invalid request")
        if 'filename' not in att or 'content_type' not in att or 'content_b64' not in att:
            raise ValueError("invalid request")
        if not isinstance(att['filename'], str) or not att['filename']:
            raise ValueError("invalid request")
        if '/' in att['filename'] or '\\' in att['filename']:
            raise ValueError("invalid request")
        if not isinstance(att['content_type'], str):
            raise ValueError("invalid request")
        if not isinstance(att['content_b64'], str):
            raise ValueError("invalid request")

    # Build email
    msg = email.mime.multipart.MIMultipart('mixed')
    msg['From'] = from_addr
    msg['To'] = ', '.join(to_list)

    # Handle RFC 2047 subject encoding
    try:
        subject.encode('ascii')
        subject_encoded = subject
    except UnicodeEncodeError:
        subject_encoded = email.mime.text._format_header(subject)

    msg['Subject'] = subject_encoded

    # Date
    msg['Date'] = formatdate(date)

    # Message-ID
    msg['Message-ID'] = message_id

    # MIME-Version
    msg['MIME-Version'] = '1.0'

    # Build body parts
    if not attachments:
        # Single text/plain part
        part = email.mime.text.MIMEText(body, 'utf-8')
        msg.attach(part)
    else:
        # First part: text/plain
        text_part = email.mime.text.MIMEText(body, 'utf-8')
        msg.attach(text_part)

        # Attachment parts
        for att in attachments:
            content = base64.b64decode(att['content_b64'])
            mime_type = att['content_type']
            part = email.mime.application.MIMEApplication(content, _subtype=mime_type.split('/')[1])
            part['Content-Disposition'] = 'attachment; filename*=UTF-8\'\'{}'.format(att['filename'])
            msg.attach(part)

    # Serialize
    msg_bytes = msg.as_bytes()

    # Check line length
    lines = msg_bytes.split(b'\n')
    for line in lines:
        if len(line) > 998:
            raise ValueError("message too long")

    # Check 7-bit clean
    msg_str = msg_bytes.decode('ascii')

    # Check line endings - all lines should end with CRLF or LF
    for line in lines[:-1]:
        if line.endswith(b'\r'):
            pass
        elif line == b'':
            pass
        else:
            raise ValueError("bad line ending")

    return msg_bytes


def main():
    try:
        stdin_data = json.loads(sys.stdin.read())
    except (json.JSONDecodeError, ValueError):
        print(json.dumps({"error": "invalid_request"}))
        return

    try:
        message_bytes = create_email_from_request(stdin_data)
    except ValueError:
        print(json.dumps({"error": "invalid_request"}))
        return

    msg_b64 = base64.b64encode(message_bytes).decode('ascii')
    sha256 = hashlib.sha256(message_bytes).hexdigest()

    print(json.dumps({
        "format": "eml",
        "message_b64": msg_b64,
        "sha256": sha256
    }))


if __name__ == '__main__':
    main()"}

